function reverseArray(arr) {
    let left = 0;
    let right = arr.length - 1;

    while (left < right) {
        // Swap elements at left and right indices
        let temp = arr[left];
        arr[left] = arr[right];
        arr[right] = temp;

        left++;
        right--;
    }

    return arr;
}

// Example usage:
const originalArray = [1, 2, 3, 4, 5];
const reversedArray = reverseArray([...originalArray]); // Use spread to avoid modifying original
console.log(reversedArray); // Output: [5, 4, 3, 2, 1]
```

This function uses a two-pointer approach to reverse the array in place, swapping elements from the start and end moving toward the center. It avoids using any built-in array methods like `reverse()`.

